head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnIdListMultiRow]<br/>Body 영역이 MultiLine 구조일때 Line 별 Column ID 를 2차원 배열로 반환합니다.",
    "validation" : [
        "Body 영역이 SingleLine 구조인 경우도 2차원 배열로 반환해야 합니다.",
        "SingleLine 구조일때 getColumnOrder(true) 메소드와 getColumnIdListMultiRow() 메소드 결과는 같아야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 구조 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  - header/gBody 각 w2:row 1개 → SingleLine 구조
    //  - Body Column : col1, col2, col3, col4 (마지막 col4 width="*")
    $c.gcm.createLabel('label="Body 영역이 SingleLine(단일 행) 구조입니다. getColumnIdListMultiRow() 는 SingleLine 도 길이 1 의 2차원 배열로 반환하며, getColumnOrder(true) 결과와 동일합니다."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "col1": "HONG", "col2": "19850315", "col3": "영업", "col4": 1000 },
        { "col1": "KIM",  "col2": "19900720", "col3": "개발", "col4": 2000 },
        { "col1": "LEE",  "col2": "19880103", "col3": "기획", "col4": 3000 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정 (createCList 공통 함수)
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (SingleLine : header/gBody 각 w2:row 1개)
    // 마지막 col4 컬럼 width="*" 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:720px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getColumnIdListMultiRow 테스트 그리드 (SingleLine)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol1" value="이름"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol2" value="생년월일"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol3" value="부서"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// getColumnIdListMultiRow 확인
//  - SingleLine 구조 → 길이 1 의 2차원 배열 반환 (예: [['col1','col2','col3','col4']])
//  - getColumnOrder(true) 결과(1차원 배열)와 동일 여부 비교 (@spec2)
scwin.btn_getColumnIdListMultiRow_onclick = function () {
    let rtnMulti = target1.getColumnIdListMultiRow();
    let rtnOrder = target1.getColumnOrder(true);

    // getColumnOrder(true) 는 1차원 배열, getColumnIdListMultiRow 는 2차원 배열(SingleLine 이므로 길이 1)
    // 동일성 비교 : SingleLine 이면 rtnMulti[0] 과 rtnOrder 가 같음
    let same = JSON.stringify(rtnMulti) === JSON.stringify([rtnOrder]);

    wf_body_bottom.getObj("scwin").setReturnValue("getColumnIdListMultiRow() → " + JSON.stringify(rtnMulti));
    wf_body_bottom.getObj("scwin").setReturnValue("getColumnOrder(true) → " + JSON.stringify(rtnOrder));
    wf_body_bottom.getObj("scwin").setReturnValue("[SingleLine 2차원 배열 반환 여부] 배열 길이 = " + rtnMulti.length);
    wf_body_bottom.getObj("scwin").setReturnValue("[getColumnOrder(true) 와 동일 여부] " + same);
}
